<script setup lang="ts">defineProps<{page:any}>();defineEmits<{(e:'go',p:number):void}>()</script>
<template><nav v-if="page&&page.last_page>1" class="c-pager" aria-label="Pagination"><button class="c-btn ghost" :disabled="page.current_page<=1" @click="$emit('go',page.current_page-1)">Previous</button><span>Page {{page.current_page}} of {{page.last_page}} · {{page.total}} total</span><button class="c-btn ghost" :disabled="page.current_page>=page.last_page" @click="$emit('go',page.current_page+1)">Next</button></nav><p v-else-if="page" class="c-muted c-pager-count">{{page.total}} total</p></template>
